676	/**
677	 * Builds a map from toolCallId → toolName by scanning all AI messages across
678	 * all namespaces in the accumulated message map.
679	 */
680	function buildToolCallIndex(
681	  nsMap: Map<NamespaceKey, MergedMessage[]>,
682	): Map<string, string> {
683	  const index = new Map<string, string>();
684	  for (const messages of nsMap.values()) {
685	    for (const msg of messages) {
686	      for (const tc of msg.tool_calls) {
687	        if (tc.id) {
688	          index.set(tc.id, tc.name);
689	        }
690	      }
691	    }
692	  }
693	  return index;
694	}
695	
696	/**
697	 * Builds a map from toolCallId → { toolName, content } by scanning all
698	 * ToolMessages across all namespaces.  Only stores entries for tools whose
699	 * rendering rule needs inline results (currently `execute` and `task`).
700	 */
701	function buildToolResultIndex(
702	  nsMap: Map<NamespaceKey, MergedMessage[]>,
703	  toolCallIndex: Map<string, string>,
704	): Map<string, { toolName: string; content: string }> {
705	  const INLINE_RESULT_TOOLS = new Set(['execute', 'task']);
706	  const index = new Map<string, { toolName: string; content: string }>();
707	
708	  for (const messages of nsMap.values()) {
709	    for (const msg of messages) {
710	      const msgType = msg.type.toLowerCase();
711	      if (msgType !== 'tool' && msgType !== 'toolmessage') continue;
712	      const tcId = msg.tool_call_id;
713	      if (!tcId) continue;
714	
715	      const toolName = toolCallIndex.get(tcId);
716	      if (!toolName || !INLINE_RESULT_TOOLS.has(toolName)) continue;
717	
718	      const content = renderContent(msg.content);
719	      index.set(tcId, { toolName, content });
720	    }
721	  }
722	  return index;
723	}
724	
725	/**
726	 * Strips a leading `cd … &&` prefix from a shell command, takes the first
727	 * meaningful command token, and truncates to ≤ 80 characters with `…`.
728	 */
729	function abbreviateCommand(command: string): string {
730	  // Strip leading `cd <dir> &&` or `cd "<dir>" &&` prefix (possibly chained).
731	  let cmd = command.trim();
732	  cmd = cmd.replace(/^(cd\s+(?:"[^"]*"|'[^']*'|\S+)\s*&&\s*)+/i, '').trim();
733	
734	  // Truncate to 80 chars with ellipsis if needed.
735	  if (cmd.length > 80) {
736	    return cmd.slice(0, 79) + '…';
737	  }
738	  return cmd;
739	}
740	
741	/**
742	 * Extracts the last meaningful output line and exit-code success flag from a
743	 * ToolMessage content string produced by `execute`.
744	 *
745	 * Content format (approximate):
746	 *   <output lines…>
747	 *   [Command succeeded with exit code 0]   ← or "failed with exit code N"
748	 *
749	 * Returns null if content is empty or no meaningful line exists.
750	 */
751	function extractExecuteResult(
752	  content: string,
753	): { summary: string; success: boolean } | null {
754	  const lines = content.split('\n').map(l => l.trim());
755	
756	  // Find the exit-code footer line.
757	  let footerIdx = -1;
758	  let success = true;
759	  for (let i = lines.length - 1; i >= 0; i--) {
760	    const line = lines[i] ?? '';
761	    const match = line.match(/^\[Command\s+(succeeded|failed)\s+with\s+exit\s+code\s+(\d+)\]$/i);
762	    if (match) {
763	      footerIdx = i;
764	      success = match[1]?.toLowerCase() === 'succeeded';
765	      break;
766	    }
767	  }
768	
769	  // Collect all non-empty, non-footer lines.
770	  const outputLines = lines.filter(
771	    (l, i) => l && i !== footerIdx,
772	  );
773	
774	  if (outputLines.length === 0) return null;
775	
776	  const summary = outputLines[outputLines.length - 1]!;
777	  return { summary, success };
778	}
