784	/**
785	 * Formats a `↳ [filename](file_path)` detail line for file tools
786	 * (`edit_file`, `write_file`, `read_file`).
787	 */
788	function formatFileToolDetail(args: unknown): string[] {
789	  if (!args || typeof args !== 'object' || Array.isArray(args)) return [];
790	  const a = args as Record<string, unknown>;
791	
792	  // edit_file / write_file use `file_path`; read_file also uses `file_path`.
793	  const filePath =
794	    typeof a['file_path'] === 'string' ? a['file_path'] :
795	    typeof a['path'] === 'string' ? a['path'] :
796	    null;
797	
798	  if (!filePath) return [];
799	
800	  const filename = filePath.split('/').pop() ?? filePath;
801	  return [`↳ [${filename}](${filePath})`];
802	}
803	
804	/**
805	 * Formats `↳ \`abbreviated_command\`` and an optional result line for `execute`.
806	 */
807	function formatExecuteDetail(
808	  args: unknown,
809	  resultEntry?: { toolName: string; content: string },
810	): string[] {
811	  const lines: string[] = [];
812	  if (args && typeof args === 'object' && !Array.isArray(args)) {
813	    const command = (args as Record<string, unknown>)['command'];
814	    if (typeof command === 'string') {
815	      lines.push('↳ `' + abbreviateCommand(command) + '`');
816	    }
817	  }
818	  if (resultEntry) {
819	    const extracted = extractExecuteResult(resultEntry.content);
820	    if (extracted) {
821	      const tick = extracted.success ? '✓' : '✗';
822	      lines.push(`↳ ${extracted.summary} ${tick}`);
823	    }
824	  }
825	  return lines;
826	}
