854	/**
855	 * Formats `write_todos` as a compact checklist.
856	 *
857	 * The args `todos` field is an array of `{ content: string; status: string }`
858	 * objects.  Each item is rendered as `- [x] content` (completed) or
859	 * `- [ ] content` (pending / in_progress).
860	 */
861	function formatWriteTodosDetail(args: unknown): string[] {
862	  if (!args || typeof args !== 'object' || Array.isArray(args)) return [];
863	  const a = args as Record<string, unknown>;
864	  const todos = a['todos'];
865	  if (!Array.isArray(todos) || todos.length === 0) return [];
866	
867	  return todos.map((todo: unknown) => {
868	    if (!todo || typeof todo !== 'object' || Array.isArray(todo)) return '- [ ] (unknown)';
869	    const t = todo as Record<string, unknown>;
870	    const content = typeof t['content'] === 'string' ? t['content'] : '(unknown)';
871	    const status = typeof t['status'] === 'string' ? t['status'] : '';
872	    const checked = status === 'completed' ? 'x' : ' ';
873	    return `- [${checked}] ${content}`;
874	  });
875	}
