1043	// Dialogue rendering — message walker
1044	// ---------------------------------------------------------------------------
1045	
1046	/**
1047	 * Renders a list of merged messages in dialogue style.
1048	 *
1049	 * - AI messages: text content as plain paragraphs; tool calls as `Tool call: \`name\`` lines.
1050	 * - ToolMessages: skipped (results already consumed inline for `execute` and `task`).
1051	 * - All other message types (Human, System, …): skipped silently.
1052	 */
1053	function renderDialogueMessages(
1054	  messages: MergedMessage[],
1055	  toolResultIndex: Map<string, { toolName: string; content: string }>,
1056	): string[] {
1057	  const lines: string[] = [];
1058	
1059	  for (const msg of messages) {
1060	    const msgType = msg.type.toLowerCase();
1061	
1062	    // Only AI messages contribute dialogue output.
1063	    if (
1064	      msgType !== 'ai' &&
1065	      msgType !== 'aimessage' &&
1066	      msgType !== 'aimessagechunk'
1067	    ) {
1068	      continue; // Skip Human, System, ToolMessage, etc.
1069	    }
1070	
1071	    // Render text content as plain paragraphs.
1072	    const contentStr = renderContent(msg.content).trim();
1073	    if (contentStr) {
1074	      lines.push(contentStr);
1075	      lines.push('');
1076	    }
1077	
1078	    // Render each tool call as a `Tool call: \`name\`` header + detail lines.
1079	    for (const tc of msg.tool_calls) {
1080	      const toolName = tc.name || 'unknown_tool';
1081	      lines.push(`Tool call: \`${toolName}\``);
1082	
1083	      // Parse args once.
1084	      let parsedArgs: unknown = null;
1085	      try {
1086	        parsedArgs = tc.args ? JSON.parse(tc.args) : null;
1087	      } catch {
1088	        parsedArgs = null;
1089	      }
1090	
1091	      // Look up result entry (only populated for `execute` and `task`).
1092	      const resultEntry = tc.id ? toolResultIndex.get(tc.id) : undefined;
1093	
1094	      const detailLines = getToolDetailLines(toolName, parsedArgs, resultEntry);
1095	      lines.push(...detailLines);
1096	      lines.push('');
1097	    }
1098	  }
1099	
1100	  return lines;
1101	}
