1131	// Public API — dialogue renderer
1132	// ---------------------------------------------------------------------------
1133	
1134	/**
1135	 * Parses a JSONL chunk file and renders its contents in a clean, chat-like
1136	 * dialogue format.
1137	 *
1138	 * Differences from `renderChunksToMarkdown`:
1139	 * - No `# Dialogue` document header or metadata table.
1140	 * - No `## Role` headings — AI text appears as plain paragraphs.
1141	 * - Tool calls are rendered as `Tool call: \`name\`` with a compact detail line
1142	 *   instead of a full JSON fenced block.
1143	 * - ToolMessages are hidden; `execute` and `task` results are shown inline with
1144	 *   their tool call.
1145	 * - No token-usage footer.
1146	 *
1147	 * @param jsonlContent  Raw JSONL string (e.g. the content of a `.jsonl` chunk file).
1148	 * @returns             A Markdown string (always ends with a trailing `\n`).
1149	 *                      Returns `*No dialogue recorded.*\n` for empty or header-only input.
1150	 */
1151	export function renderChunksToDialogue(jsonlContent: string): string {
1152	  const rawLines = jsonlContent.split('\n');
1153	  const nonEmptyLines = rawLines.map(l => l.trim()).filter(Boolean);
1154	
1155	  // --- Header validation (same as renderChunksToMarkdown) ---
1156	  let dataLines: string[];
1157	  if (nonEmptyLines.length === 0) {
1158	    dataLines = [];
1159	  } else {
1160	    const firstLine = nonEmptyLines[0]!;
1161	    dataLines = isValidHeader(firstLine)
1162	      ? nonEmptyLines.slice(1)
1163	      : nonEmptyLines;
1164	  }
1165	
1166	  // --- Parse chunk lines ---
1167	  const records: Array<{ namespace: string[]; msg: Record<string, JsonValue> }> = [];
1168	  for (const line of dataLines) {
1169	    const parsed = parseChunkLine(line);
1170	    if (parsed) {
1171	      records.push({ namespace: parsed.namespace, msg: parsed.msg });
1172	    }
1173	  }
1174	
1175	  // --- Accumulate chunks into merged messages per namespace ---
1176	  const nsMap = accumulateChunks(records);
1177	
1178	  if (nsMap.size === 0) {
1179	    return '*No dialogue recorded.*\n';
1180	  }
1181	
1182	  // --- Build correlation indexes ---
1183	  const toolCallIndex = buildToolCallIndex(nsMap);
1184	  const toolResultIndex = buildToolResultIndex(nsMap, toolCallIndex);
1185	
1186	  // --- Render per namespace (main agent first, sub-agents next) ---
1187	  const lines: string[] = [];
1188	
1189	  const mainMessages = nsMap.get('');
1190	  if (mainMessages && mainMessages.length > 0) {
1191	    lines.push(...renderDialogueNamespaceBlock('', mainMessages, toolResultIndex, false));
1192	  }
1193	
1194	  for (const [nsKey, messages] of nsMap.entries()) {
1195	    if (nsKey === '') continue;
1196	    if (messages.length > 0) {
1197	      lines.push(...renderDialogueNamespaceBlock(nsKey, messages, toolResultIndex, true));
1198	    }
1199	  }
1200	
1201	  // Remove any trailing blank lines before adding the final newline.
1202	  while (lines.length > 0 && lines[lines.length - 1] === '') {
1203	    lines.pop();
1204	  }
1205	
1206	  return lines.join('\n') + '\n';
1207	}

