1000	
1001	/**
1002	 * Returns 0–N `↳ …` detail lines for a given tool call.  Dispatches to the
1003	 * appropriate per-family formatter helper.
1004	 *
1005	 * @param name         Tool name.
1006	 * @param args         Parsed tool arguments (object or null).
1007	 * @param resultEntry  Optional result index entry for tools needing inline results.
1008	 */
1009	function getToolDetailLines(
1010	  name: string,
1011	  args: unknown,
1012	  resultEntry?: { toolName: string; content: string },
1013	): string[] {
1014	  // File family
1015	  if (name === 'edit_file' || name === 'write_file' || name === 'read_file') {
1016	    return formatFileToolDetail(args);
1017	  }
1018	  // Execution family
1019	  if (name === 'execute') {
1020	    return formatExecuteDetail(args, resultEntry);
1021	  }
1022	  // Task family
1023	  if (name === 'task') {
1024	    return formatTaskDetail(args, resultEntry);
1025	  }
1026	  // Todo family
1027	  if (name === 'write_todos') {
1028	    return formatWriteTodosDetail(args);
1029	  }
1030	  // Search family — no detail line
1031	  if (name === 'glob' || name === 'grep' || name === 'ls') {
1032	    return [];
1033	  }
1034	  // Ledger family
1035	  if (name.startsWith('ledger_')) {
1036	    return formatLedgerToolDetail(name, args);
1037	  }
1038	  // Default / unknown — no detail line, header always shown by caller
1039	  return [];
1040	}
